SELECT 
FROM robot r
LEFT JOIN brand b ON b.id = r.brand_id AND b.deleted = 0
LEFT JOIN robot_category c ON c.id = r.category_id AND c.deleted = 0

    r.deleted = 0

        AND r.category_id IN
        #{cid}

    AND r.brand_id = #{q.brandId}
    AND r.series_id = #{q.seriesId}

        AND (
            r.name LIKE CONCAT('%', #{q.keyword}, '%')
            OR r.model LIKE CONCAT('%', #{q.keyword}, '%')
            OR r.subtitle LIKE CONCAT('%', #{q.keyword}, '%')
            OR b.name LIKE CONCAT('%', #{q.keyword}, '%')
        )

    AND r.guide_price >= #{q.minPrice}
    AND r.guide_price <= #{q.maxPrice}
    AND r.release_date >= #{q.releaseStart}
    AND r.release_date <= #{q.releaseEnd}

        AND EXISTS (
            SELECT 1 FROM robot_tag t WHERE t.robot_id = r.id AND t.tag_type = 'scene'
            AND t.tag_value IN
            #{v}
        )


        AND EXISTS (
            SELECT 1 FROM robot_tag t WHERE t.robot_id = r.id AND t.tag_type = 'dev'
            AND t.tag_value IN
            #{v}
        )


        AND EXISTS (
            SELECT 1 FROM robot_tag t WHERE t.robot_id = r.id AND t.tag_type = 'ai'
            AND t.tag_value IN
            #{v}
        )



    ORDER BY r.view_count DESC, r.hot_score DESC
    ORDER BY r.guide_price ASC, r.hot_score DESC
    ORDER BY r.guide_price DESC, r.hot_score DESC
    ORDER BY r.release_date DESC, r.hot_score DESC
    ORDER BY r.score DESC, r.hot_score DESC
    ORDER BY r.hot_score DESC, r.view_count DESC
